import{settle,money,csv}from'./core.js';
import{t,languageMenu,bindLanguage}from'./i18n.js';
document.title=t('title');
document.body.innerHTML=`<header><a class="brand" href="./">S<span>÷</span>C</a><span class="local">● ${t('local')}</span>${languageMenu()}</header><main><section class="intro"><p class="eyebrow">SHARED COSTS / 03</p><h1>${t('headline')}<br><em>${t('accent')}</em></h1><p>${t('intro')}</p></section><section class="workspace"><div class="topline"><h2>01 <span>${t('settings')}</span></h2><button id="example" class="quiet">${t('example')}</button></div><div class="settings"><label>${t('start')}<input id="start" type="date" value="2026-10-01"></label><label>${t('end')}<input id="end" type="date" value="2026-10-31"></label><label>${t('currency')}<input id="currency" value="KRW" maxlength="12"></label><label>${t('decimals')}<select id="decimals"><option value="0">0</option><option value="2">2</option><option value="3">3</option></select></label></div><p class="hint">${t('unitNote')}</p><p class="hint">${t('limits')}</p></section><section class="workspace"><div class="topline"><h2>02 <span>${t('people')}</span></h2><button id="addPerson" class="secondary">+ ${t('addPerson')}</button></div><div class="tablewrap"><table><thead><tr>${['name','moveIn','moveOut','area','usage','weight','remove'].map(key=>'<th>'+t(key)+'</th>').join('')}</tr></thead><tbody id="people"></tbody></table></div></section><section class="workspace"><div class="topline"><h2>03 <span>${t('expenses')}</span></h2><button id="addExpense" class="secondary">+ ${t('addExpense')}</button></div><div class="tablewrap"><table><thead><tr>${['label','amount','payer','rule','person','remove'].map(key=>'<th>'+t(key)+'</th>').join('')}</tr></thead><tbody id="expenses"></tbody></table></div><div class="actions"><button id="calculate" class="primary">${t('calculate')}</button></div><p id="message" role="status" aria-live="polite"></p></section><section id="results" class="workspace" hidden><div class="topline"><h2>04 <span>${t('results')}</span></h2><span id="total" class="total"></span></div><div class="actions"><button id="csv" class="secondary">${t('csv')}</button><button id="copy" class="secondary">${t('copy')}</button></div><div class="tablewrap"><table id="balances"></table></div><h3>${t('transfers')}</h3><div class="tablewrap"><table id="transfers"></table></div><h3>${t('details')}</h3><div class="tablewrap"><table id="details"></table></div></section><details><summary>${t('rules')}</summary><p id="help"></p><p><a href="https://tc39.es/ecma262/multipage/numbers-and-dates.html#sec-bigint-objects" target="_blank" rel="noreferrer">ECMAScript BigInt</a> · <a href="https://www.rfc-editor.org/rfc/rfc4180" target="_blank" rel="noreferrer">RFC 4180</a> · <a href="https://owasp.org/www-community/attacks/CSV_Injection" target="_blank" rel="noreferrer">OWASP CSV Injection</a></p></details></main><footer><span>${t('privacy')}</span><a href="https://nanalab.kr/apps/">More Apps ↗</a></footer>`;
bindLanguage();const note=document.createElement('p');note.className='hint';note.textContent=t('exportNote');document.getElementById('results').append(note);const $=id=>document.getElementById(id);$('help').textContent=t('help');let people=[],expenses=[],result=null;
const ruleKeys={days:'days',area:'areaRule',usage:'usageRule',weight:'weightRule',personal:'personal'};
function message(text,error=false){$('message').textContent=text;$('message').className=error?'error':'';}
function invalidate(){result=null;$('results').hidden=true;message(t('stale'));}
function input(value,label,change,type='text',max='30'){const el=document.createElement('input');el.type=type;el.value=value;el.setAttribute('aria-label',label);el.maxLength=Number(max);el.oninput=e=>{change(e.target.value);invalidate();};return el;}
function cell(row,el){const td=document.createElement('td');td.append(el);row.append(td);}
function select(value,options,label,change){const el=document.createElement('select');el.setAttribute('aria-label',label);for(const [v,text]of options){const o=document.createElement('option');o.value=v;o.textContent=text;el.append(o);}el.value=String(value);el.onchange=e=>{change(e.target.value);invalidate();};return el;}
function removeButton(label,action){const b=document.createElement('button');b.textContent='×';b.className='remove';b.setAttribute('aria-label',t('remove')+' '+label);b.onclick=action;return b;}
function renderPeople(){$('people').replaceChildren();people.forEach((p,i)=>{const row=document.createElement('tr');for(const [key,label,type,max]of [['name','name','text','60'],['start','moveIn','date','30'],['end','moveOut','date','30'],['area','area','text','30'],['usage','usage','text','30'],['weight','weight','text','30']])cell(row,input(p[key],t(label)+' '+(i+1),v=>{p[key]=v;if(key==='name')renderExpenses();},type,max));cell(row,removeButton(String(i+1),()=>{people.splice(i,1);for(const e of expenses)for(const key of ['payer','person'])e[key]=Number(e[key])===i?-1:Number(e[key])>i?Number(e[key])-1:Number(e[key]);invalidate();renderPeople();renderExpenses();}));$('people').append(row);});$('addPerson').disabled=people.length>=12;}
function renderExpenses(){$('expenses').replaceChildren();const names=[[-1,'—'],...people.map((p,i)=>[i,p.name||String(i+1)])];expenses.forEach((e,i)=>{const row=document.createElement('tr');cell(row,input(e.label,t('label')+' '+(i+1),v=>e.label=v,'text','120'));cell(row,input(e.amount,t('amount')+' '+(i+1),v=>e.amount=v));cell(row,select(e.payer,names,t('payer')+' '+(i+1),v=>e.payer=v));cell(row,select(e.rule,Object.entries(ruleKeys).map(([v,k])=>[v,t(k)]),t('rule')+' '+(i+1),v=>{e.rule=v;renderExpenses();}));const person=select(e.person,names,t('person')+' '+(i+1),v=>e.person=v);person.disabled=e.rule!=='personal';cell(row,person);cell(row,removeButton(String(i+1),()=>{expenses.splice(i,1);invalidate();renderExpenses();}));$('expenses').append(row);});$('addExpense').disabled=expenses.length>=40;}
function table(id,headers,rows){const el=$(id);el.replaceChildren();const head=document.createElement('thead'),tr=document.createElement('tr');for(const value of headers){const th=document.createElement('th');th.textContent=value;tr.append(th);}head.append(tr);el.append(head);const body=document.createElement('tbody');for(const values of rows){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=String(value);tr.append(td);}body.append(tr);}if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=headers.length;td.textContent=t('none');tr.append(td);body.append(tr);}el.append(body);}
const m=n=>money(n,result.decimals);const currency=()=>$('currency').value.trim();
function calculate(){try{if(!currency()||currency().length>12)throw Error('currencyError');result=settle({start:$('start').value,end:$('end').value,decimals:Number($('decimals').value),people,expenses});$('total').textContent=t('total')+' '+m(result.total)+' '+currency();table('balances',['name','days','paid','due','balance'].map(t),result.members.map(p=>[p.name,p.days,m(p.paid),m(p.due),m(p.balance)]));table('transfers',['from','to','amount'].map(t),result.transfers.map(p=>[result.members[p.from].name,result.members[p.to].name,m(p.amount)]));table('details',[t('label'),t('rule'),t('amount'),...result.members.map(p=>p.name)],result.details.map(e=>[e.label,t(ruleKeys[e.rule]),m(e.amount),...e.shares.map(m)]));$('results').hidden=false;message(t('ready'));}catch(e){result=null;$('results').hidden=true;message(t(e.message,e),true);}}
function reportRows(){const headers=[t('status'),t('label'),t('name'),t('paid'),t('due'),t('balance'),t('from'),t('to'),t('amount')+' ('+currency()+')',t('rule'),t('days')],rows=[headers];for(const p of result.members)rows.push([t('results'),'',p.name,m(p.paid),m(p.due),m(p.balance),'','','','',p.days]);for(const p of result.transfers)rows.push([t('transfers'),'','','','','',result.members[p.from].name,result.members[p.to].name,m(p.amount),'','']);for(const e of result.details)for(const [i,share]of e.shares.entries())rows.push([t('details'),e.label,result.members[i].name,'',m(share),'','','',m(e.amount),t(ruleKeys[e.rule]),'']);return rows;}
$('calculate').onclick=calculate;$('addPerson').onclick=()=>{if(people.length>=12)return;people.push({name:'',start:'',end:'',area:'1',usage:'1',weight:'1'});invalidate();renderPeople();renderExpenses();};$('addExpense').onclick=()=>{if(expenses.length>=40)return;expenses.push({label:'',amount:'',payer:0,rule:'days',person:0});invalidate();renderExpenses();};
for(const id of ['start','end','currency','decimals'])$(id).oninput=invalidate;
$('csv').onclick=()=>{if(!result)return;const url=URL.createObjectURL(new Blob(['\uFEFF'+csv(reportRows())],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='shared-costs.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('copy').onclick=async()=>{if(!result)return;const lines=[t('title')+' · '+currency(),...result.members.map(p=>p.name+': '+t('paid')+' '+m(p.paid)+' / '+t('due')+' '+m(p.due)+' / '+t('balance')+' '+m(p.balance)),...result.transfers.map(p=>result.members[p.from].name+' → '+result.members[p.to].name+': '+m(p.amount))];try{await navigator.clipboard.writeText(lines.join('\n'));message(t('copied'));}catch{message(t('copyFail'),true);}};
$('example').onclick=()=>{$('start').value='2026-10-01';$('end').value='2026-10-31';$('currency').value='KRW';$('decimals').value='0';people=[{name:'A',start:'',end:'',area:'12',usage:'20',weight:'1'},{name:'B',start:'2026-10-16',end:'',area:'15',usage:'12',weight:'1'},{name:'C',start:'',end:'',area:'10',usage:'18',weight:'2'}];expenses=[{label:t('sampleRent'),amount:'900000',payer:0,rule:'area',person:0},{label:t('sampleExpense'),amount:'150000',payer:1,rule:'usage',person:0},{label:t('samplePersonal'),amount:'20000',payer:2,rule:'personal',person:0}];renderPeople();renderExpenses();calculate();};$('example').click();
